def fact(n):
    return fact_[n]


def get_perm(n, k):
    if k > fact(n):
        exit(123)

    if n == 1:
        return [1]

    k -= 1
    res = []
    not_used = [i for i in range(1, n + 1)]
    size = fact(n - 1)
    for i in range(n):
        cnt = k // size
        res.append(not_used[cnt])
        not_used.pop(cnt)
        k %= size
        if i != n - 1:
            size //= (n - 1 - i)
    return res[::]


