def prime_factor(n):
    res = collections.defaultdict(int)

    i = 2
    while i * i <= n:
        cnt = 0
        while n % i == 0:
            n //= i
            cnt += 1
        if cnt > 0: res[i] = cnt
        i += 1
    if n != 1: res[n] = 1

    return res

