["def f(n):
	left, right = -1, n + 1
	while right - left > 1:
		mid = (left + right) // 2
		x = 6 * mid * (mid + 1) // 2 + 5 * (mid + 1)
		if x > n:
			right = mid
		else:
			left = mid
	if left >= 0:
		mid = left
		x = 6 * mid * (mid + 1) // 2 + 5 * (mid + 1)
		n -= x
	return (n, left + 1)

